        n += rest >= Fraction(1, 2)
    elif method == HALF_EVEN:
        n += rest > Fraction(1, 2) or (rest == Fraction(1, 2) and n % 2 == 1)
    return Decimal((int(value.is_signed()), tuple(int(c) for c in str(int(n) * coef)), exp))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` decides ties and direction."""
    return _round(value, step, method)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, cut down to `step`, adding up to the rounded sum.

    What the cuts lost against the rounded total goes on the last amount
    that is not zero.
    """
